# Add debug print when cache is set
old = """      if(clipamount) {
        pp->cache_size = clipamount;
        pp->cache = malloc(pp->cache_size);
        if(pp->cache)
          memcpy(pp->cache, pp->linestart_resp, pp->cache_size);
        else
          return CURLE_OUT_OF_MEMORY;
      }"""
new = """      if(clipamount) {
        fprintf(stderr, "DBG cache SET: clipamount=%ld nread=%zu buffer_size=%zu perline=%ld linestart_offset=%ld\\n", (long)clipamount, pp->nread_resp, data->set.buffer_size, (long)perline, (long)(pp->linestart_resp-buf));
        pp->cache_size = clipamount;
        pp->cache = malloc(pp->cache_size);
        if(pp->cache)
          memcpy(pp->cache, pp->linestart_resp, pp->cache_size);
        else
          return CURLE_OUT_OF_MEMORY;
      }"""
assert old in content
content = content.replace(old, new)
with open('lib/pingpong.c','w') as f:
    f.write(content)
print("patched")
EOF
